package com.celebritymode.chat;

import static org.junit.Assert.*;

import com.celebritymode.fan.FanPersonality;

import org.junit.Test;

import java.util.*;

public class FanChatManagerTest {
    @Test
    public void quoteParsing() {
        assertEquals(
                Arrays.asList("hello, there", "nice cape"),
                FanQuoteLibrary.parse(" hello, there \n\n nice cape "));
        assertEquals(Arrays.asList("hi", "gz"), FanQuoteLibrary.parse(" hi, ,gz, "));
        assertEquals(Arrays.asList("hi", "gz"), FanQuoteLibrary.parse("hi\r\ngz"));
        assertTrue(FanQuoteLibrary.parse(" , , ").isEmpty());
        assertTrue(FanQuoteLibrary.parse(null).isEmpty());
        assertTrue(
                FanQuoteLibrary.pool(
                                FanPersonality.EXCITED,
                                CustomQuoteMode.CUSTOM_ONLY,
                                FanQuoteLibrary.parse(""))
                        .isEmpty());
    }

    @Test
    public void offAndEmptyCustomModeSuppressEventChat() {
        com.celebritymode.TestScene scene = new com.celebritymode.TestScene();
        scene.populate();
        FanChatManager chat = new FanChatManager(new Random(8));
        chat.configure(ChatFrequency.OFF, CustomQuoteMode.MIXED, "", 0);
        for (com.celebritymode.fan.FanEntity fan : scene.manager.getFans()) fan.overheadText = null;
        chat.react(scene.manager.getFans(), 1, new String[] {"gz"});
        for (com.celebritymode.fan.FanEntity fan : scene.manager.getFans())
            assertNull(fan.overheadText);
        chat.configure(ChatFrequency.SPAM, CustomQuoteMode.CUSTOM_ONLY, "", 0);
        for (int i = 0; i < 100; i++) chat.tick(scene.manager.getFans(), i);
        chat.react(scene.manager.getFans(), 100, new String[] {"gz"});
        for (com.celebritymode.fan.FanEntity fan : scene.manager.getFans())
            assertNull(fan.overheadText);
    }

    @Test
    public void spamKeepsMostOfTheCrowdTalking() {
        com.celebritymode.TestScene scene = new com.celebritymode.TestScene();
        scene.config.size = 30;
        scene.populate();
        FanChatManager chat = new FanChatManager(new Random(18));
        chat.configure(ChatFrequency.SPAM, CustomQuoteMode.BUILT_IN_ONLY, "", 0);
        for (com.celebritymode.fan.FanEntity fan : scene.manager.getFans()) {
            fan.nextChatTick = 0;
            fan.overheadText = null;
        }
        int busyTicks = 0, messages = 0;
        for (int tick = 1; tick <= 100; tick++) {
            int[] old = new int[30];
            for (int i = 0; i < 30; i++) old[i] = scene.manager.getFans().get(i).overheadExpiryTick;
            chat.tick(scene.manager.getFans(), tick);
            int speaking = 0;
            for (int i = 0; i < 30; i++) {
                com.celebritymode.fan.FanEntity fan = scene.manager.getFans().get(i);
                if (fan.overheadText != null) speaking++;
                if (old[i] != fan.overheadExpiryTick) messages++;
            }
            if (speaking >= 20) busyTicks++;
        }
        assertTrue("Near-constant visible chatter", busyTicks >= 95);
        assertTrue("Many messages each second", messages > 1200);
    }

    @Test
    public void fansRememberRecentLinesAndContextChangesReachTheCrowd() {
        com.celebritymode.TestScene scene = new com.celebritymode.TestScene();
        scene.populate();
        com.celebritymode.fan.FanEntity fan = scene.manager.getFans().get(0);
        List<com.celebritymode.fan.FanEntity> fans = Collections.singletonList(fan);
        FanChatManager chat = new FanChatManager(new Random(4));
        chat.clear(fans);
        chat.configure(ChatFrequency.SPAM, CustomQuoteMode.BUILT_IN_ONLY, "", 0);
        chat.setContext(
                new FanChatContext(
                        "LocalHero",
                        "",
                        "Goblin",
                        FanChatContext.Activity.COMBAT,
                        null,
                        0,
                        0,
                        false,
                        false));
        Deque<String> recent = new ArrayDeque<>();
        String previous = null;
        int messages = 0, targetLines = 0, repeat = 0;
        for (int tick = 1; tick < 400; tick++) {
            int expiry = fan.overheadExpiryTick;
            chat.tick(fans, tick);
            if (expiry == fan.overheadExpiryTick) continue;
            String line = fan.overheadText.toLowerCase(Locale.ENGLISH).replaceAll("[^a-z0-9 ]", "");
            assertNotEquals(previous, line);
            if (recent.contains(line)) repeat++;
            recent.addLast(line);
            if (recent.size() > 12) recent.removeFirst();
            if (line.contains("goblin")) targetLines++;
            previous = line;
            messages++;
        }
        assertTrue(messages > 200);
        assertTrue(targetLines > 30);
        assertTrue("Per-fan recent duplicates: " + repeat, repeat <= 2);
        chat.setContext(FanChatContext.idle("New Name", ""));
        for (int tick = 400; tick < 440; tick++) {
            int expiry = fan.overheadExpiryTick;
            chat.tick(fans, tick);
            if (expiry != fan.overheadExpiryTick) {
                assertFalse(fan.overheadText.toLowerCase(Locale.ENGLISH).contains("goblin"));
                assertFalse(fan.overheadText.contains("LocalHero"));
            }
        }
    }

    @Test
    public void customLevelEventsUseActualLevelAndRemainVisibleBeforeNextChatter() {
        com.celebritymode.TestScene scene = new com.celebritymode.TestScene();
        scene.populate();
        FanChatManager chat = new FanChatManager(new Random(9));
        chat.configure(
                ChatFrequency.SPAM, CustomQuoteMode.CUSTOM_ONLY, "{player} {level} {skill}", 0);
        chat.setContext(FanChatContext.idle("LocalHero", ""));
        chat.level(scene.manager.getFans(), 10, net.runelite.api.Skill.MINING, 82);
        int reactions = 0;
        for (com.celebritymode.fan.FanEntity fan : scene.manager.getFans()) {
            if ("LocalHero 82 Mining".equals(fan.overheadText)) {
                assertTrue(fan.nextChatTick >= 13);
                reactions++;
            }
        }
        assertEquals(2, reactions);
    }

    @Test
    public void seededSchedulingBounds() {
        FanChatManager manager = new FanChatManager(new Random(10));
        for (ChatFrequency f : ChatFrequency.values()) {
            manager.configure(f, CustomQuoteMode.MIXED, "", 100);
            if (f == ChatFrequency.OFF) {
                assertEquals(Integer.MAX_VALUE, manager.getNextTick());
                manager.tick(Collections.emptyList(), 10000);
                assertEquals(Integer.MAX_VALUE, manager.getNextTick());
            } else
                for (int tick = 100; tick < 1000; tick += 30) {
                    manager.configure(f, CustomQuoteMode.MIXED, "", tick);
                    int delay = manager.getNextTick() - tick;
                    assertTrue(delay >= f.minimumTicks && delay <= f.maximumTicks);
                }
        }
    }

    @Test
    public void avoidsImmediateDuplicateWheneverPossible() {
        FanChatManager manager = new FanChatManager(new Random(8));
        String previous = null;
        for (int i = 0; i < 100; i++) {
            String q = manager.choose(Arrays.asList("gz", "gz", "hi"));
            assertNotEquals(previous, q);
            previous = q;
        }
        assertNull(manager.choose(Collections.emptyList()));
        assertEquals("only", manager.choose(Collections.singletonList("only")));
    }
}

package com.celebritymode.chat;

import static org.junit.Assert.*;

import com.celebritymode.TestScene;

import net.runelite.api.*;

import org.junit.Test;

public class FanActivityTrackerTest {
    @Test
    public void loginXpIsNotAnActivityButRealGainsAreAndExpire() {
        TestScene scene = new TestScene();
        scene.skillXp.put(Skill.WOODCUTTING, 40000);
        FanActivityTracker tracker = new FanActivityTracker();
        tracker.experience(Skill.WOODCUTTING, 40000, 1);
        assertEquals(FanChatContext.Activity.IDLE, observe(tracker, scene, 1).activity);
        tracker.experience(Skill.WOODCUTTING, 40075, 2);
        FanChatContext context = observe(tracker, scene, 3);
        assertEquals(FanChatContext.Activity.SKILLING, context.activity);
        assertEquals(Skill.WOODCUTTING, context.skill);
        assertEquals(75, context.gainedXp);
        assertEquals(70, context.level);
        assertEquals(
                FanChatContext.Activity.RUNNING,
                tracker.observe(scene.client, scene.player, "", true, true, 4).activity);
        assertEquals(FanChatContext.Activity.IDLE, observe(tracker, scene, 13).activity);
        assertNull(observe(tracker, scene, 13).skill);
        tracker.clear();
        assertEquals(FanChatContext.Activity.IDLE, observe(tracker, scene, 1).activity);
    }

    @Test
    public void bankMovementGearAndNoncombatMagicUseObservedState() {
        TestScene scene = new TestScene();
        FanActivityTracker tracker = new FanActivityTracker();
        tracker.observe(scene.client, scene.player, "bow", true, true, 1);
        assertEquals(
                FanChatContext.Activity.WALKING,
                tracker.observe(scene.client, scene.player, "bow", true, false, 2).activity);
        FanChatContext changed =
                tracker.observe(scene.client, scene.player, "staff", true, true, 3);
        assertEquals(FanChatContext.Activity.RUNNING, changed.activity);
        assertTrue(changed.gearChanged);
        assertFalse(
                tracker.observe(scene.client, scene.player, "staff", false, false, 12).gearChanged);
        tracker.experience(Skill.MAGIC, 65, 12);
        assertEquals(FanChatContext.Activity.SKILLING, observe(tracker, scene, 13).activity);
        scene.bankOpen = true;
        assertEquals(FanChatContext.Activity.BANKING, observe(tracker, scene, 13).activity);
    }

    @Test
    public void TalkingToNpcIsNotFightingAndLowHealthNeedsCombat() {
        TestScene scene = new TestScene();
        scene.interacting =
                TestScene.proxy(
                        NPC.class,
                        (method, args) -> {
                            if (method.equals("getName")) return "<col=ffff00>Goblin</col>";
                            if (method.equals("getCombatLevel")) return 2;
                            if (method.equals("getHealthRatio")) return -1;
                            return null;
                        });
        scene.hp = 10;
        FanActivityTracker tracker = new FanActivityTracker();
        assertEquals(FanChatContext.Activity.IDLE, observe(tracker, scene, 1).activity);
        assertFalse(observe(tracker, scene, 1).lowHealth);
        tracker.menu("Attack", 2);
        FanChatContext fighting = observe(tracker, scene, 2);
        assertEquals(FanChatContext.Activity.COMBAT, fighting.activity);
        assertEquals("Goblin", fighting.target);
        assertTrue(fighting.lowHealth);
        scene.interacting = null;
        assertFalse(observe(tracker, scene, 3).lowHealth);
        assertEquals("", observe(tracker, scene, 3).target);
    }

    private static FanChatContext observe(FanActivityTracker tracker, TestScene scene, int tick) {
        return tracker.observe(scene.client, scene.player, "", false, false, tick);
    }
}

package com.celebritymode.chat;

import static org.junit.Assert.*;

import com.celebritymode.fan.FanPersonality;

import org.junit.Test;

import java.util.*;

public class FanDialogueGeneratorTest {
    @Test
    public void composableDialogueHasBroadVarietyAndUsesCurrentName() {
        Random random = new Random(5);
        Set<String> lines = new HashSet<>();
        int personalized = 0;
        for (int i = 0; i < 2000; i++) {
            String quote =
                    FanDialogueGenerator.generate(
                            random,
                            FanPersonality.values()[i % 6],
                            "Current Hero",
                            "Tumeken's shadow");
            if (quote.toLowerCase(Locale.ENGLISH).contains("current hero")) personalized++;
            assertFalse(quote.toLowerCase(Locale.ENGLISH).contains("zezima"));
            assertTrue(quote.length() <= 100);
            lines.add(quote);
        }
        assertTrue("Composed dialogue variety: " + lines.size(), lines.size() > 400);
        assertTrue(
                "Names mixed with natural observations",
                personalized > 1000 && personalized < 1950);
    }

    @Test
    public void broadCorpusSelectsRelevantObservationsWithoutUnresolvedTokens() {
        Random random = new Random(84);
        Set<String> lines = new HashSet<>();
        int mining = 0, targets = 0, warning = 0;
        for (int i = 0; i < 18000; i++) {
            net.runelite.api.Skill skill =
                    new net.runelite.api.Skill[] {
                                net.runelite.api.Skill.MINING, net.runelite.api.Skill.FISHING,
                                net.runelite.api.Skill.WOODCUTTING, net.runelite.api.Skill.AGILITY,
                                net.runelite.api.Skill.HERBLORE, net.runelite.api.Skill.CRAFTING
                            }
                            [i % 6];
            FanChatContext.Activity activity = FanChatContext.Activity.values()[i / 6 % 6];
            FanChatContext context =
                    new FanChatContext(
                            "Current Hero",
                            "Tumeken's shadow",
                            activity == FanChatContext.Activity.COMBAT ? "Goblin" : "",
                            activity,
                            activity == FanChatContext.Activity.SKILLING ? skill : null,
                            80,
                            100,
                            activity == FanChatContext.Activity.COMBAT,
                            i % 7 == 0);
            String line =
                    FanDialogueGenerator.generate(random, FanPersonality.values()[i % 6], context);
            assertFalse(line, line.contains("{") || line.contains("}"));
            assertTrue(line.length() <= 100);
            if (line.toLowerCase(Locale.ENGLISH).contains("goblin")) targets++;
            if (line.toLowerCase(Locale.ENGLISH).contains("hp") || line.contains("food check"))
                warning++;
            if (line.toLowerCase(Locale.ENGLISH).contains("mining")) mining++;
            if (activity != FanChatContext.Activity.COMBAT)
                assertFalse(line, line.toLowerCase(Locale.ENGLISH).contains("goblin"));
            lines.add(line);
        }
        assertTrue("Distinct composed lines: " + lines.size(), lines.size() > 2500);
        assertTrue("Combat target observations", targets > 500);
        assertTrue("Situational health warnings", warning > 100);
        assertTrue("Actual skill observations", mining > 60);
    }

    @Test
    public void levelReactionsNameTheActualSkillAndLevel() {
        FanChatContext context =
                new FanChatContext(
                        "LocalHero",
                        "",
                        "",
                        FanChatContext.Activity.SKILLING,
                        net.runelite.api.Skill.MINING,
                        82,
                        0,
                        false,
                        false);
        Random random = new Random(4);
        Set<String> lines = new HashSet<>();
        for (int i = 0; i < 100; i++) {
            String quote = FanDialogueGenerator.level(context, random);
            assertTrue(quote.contains("LocalHero"));
            assertTrue(quote.contains("mining") || quote.contains("82"));
            assertFalse(quote.contains("{"));
            lines.add(quote);
        }
        assertTrue(lines.size() >= 8);
    }

    @Test
    public void customQuotesAndEventsUseLiveContextWithoutChangingTheirSource() {
        FanChatManager chat = new FanChatManager(new Random(1));
        chat.configure(ChatFrequency.SPAM, CustomQuoteMode.CUSTOM_ONLY, "{player} nice {gear}", 0);
        chat.setContext("<col=ff0000>Old Name</col>", "bow");
        assertEquals(
                "Old Name nice bow", chat.choose(FanQuoteLibrary.parse("{player} nice {gear}")));
        chat.setContext("New Name", "staff");
        assertEquals(
                "New Name nice staff", chat.choose(FanQuoteLibrary.parse("{player} nice {gear}")));
        chat.setContext(null, null);
        assertEquals("you nice fit", chat.choose(FanQuoteLibrary.parse("{player} nice {gear}")));
    }
}

package com.celebritymode.ui;

import static org.junit.Assert.*;
import com.celebritymode.chat.ChatFrequency;
import org.junit.Test;
import javax.swing.*;

public class CelebrityModePanelTest {
    @Test
    public void crowdControlsPersistAndRefreshWithoutFeedbackWrites() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            PanelFixture config = new PanelFixture();
            CelebrityModePanel panel = new CelebrityModePanel(config, config::write);
            assertEquals(0, config.writes);
            JSlider slider = (JSlider) PanelFixture.find(panel, "crowdSizeSlider");
            slider.setValueIsAdjusting(true);
            slider.setValue(72);
            assertEquals("Dragging doesn't resize repeatedly", 0, config.writes);
            slider.setValueIsAdjusting(false);
            assertEquals(72, config.crowdSize());
            assertEquals(1, config.writes);
            JSpinner count = (JSpinner) PanelFixture.find(panel, "crowdSize");
            count.setValue(100);
            assertEquals(100, config.crowdSize());
            config.values.put("crowdSize", 42);
            int writes = config.writes;
            panel.refresh("crowdSize");
            assertEquals(42, count.getValue());
            assertEquals(writes, config.writes);
            JCheckBox show = (JCheckBox) PanelFixture.find(panel, "showCrowd");
            show.doClick();
            assertFalse(config.showCrowd());
            PanelFixture.button(panel, "Small audience").doClick();
            assertEquals(8, config.crowdSize());
            assertEquals(ChatFrequency.LOW, config.chatFrequency());
            assertFalse("Presets don't unhide a paused scene", config.showCrowd());
        });
    }

    @Test
    public void inboxControlsPersistIndependentlyAndKeepQuoteDrafts() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            PanelFixture config = new PanelFixture();
            config.values.put("showCrowd", false);
            config.values.put("chatFrequency", ChatFrequency.OFF);
            CelebrityModePanel panel = new CelebrityModePanel(config, config::write);
            PanelFixture.button(panel, "Dialogue").doClick();
            JTextArea text = (JTextArea) PanelFixture.find(panel, "customQuotes");
            text.setText("draft for the next take");
            JCheckBox enabled = (JCheckBox) PanelFixture.find(panel, "enableFanPms");
            assertFalse(enabled.isSelected());
            enabled.doClick();
            assertTrue(config.enableFanPms());
            JComboBox<?> intensity = (JComboBox<?>) PanelFixture.find(panel, "pmTrafficIntensity");
            intensity.setSelectedItem(com.celebritymode.pm.TrafficIntensity.PEAK_WORLD_RECORD);
            assertEquals(com.celebritymode.pm.TrafficIntensity.PEAK_WORLD_RECORD, config.pmTrafficIntensity());
            ((JCheckBox) PanelFixture.find(panel, "pmNotificationSound")).doClick();
            assertTrue(config.pmNotificationSound());
            assertEquals("draft for the next take", text.getText());
            assertFalse(config.showCrowd());
            assertEquals(ChatFrequency.OFF, config.chatFrequency());
            config.values.put("enableFanPms", false);
            panel.refresh("enableFanPms");
            assertFalse(enabled.isSelected());
        });
    }

    @Test
    public void quoteDraftsSurviveOtherEditsAndExternalChanges() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            PanelFixture config = new PanelFixture();
            config.values.put("customQuotes", "original");
            CelebrityModePanel panel = new CelebrityModePanel(config, config::write);
            PanelFixture.button(panel, "Dialogue").doClick();
            JTextArea text = (JTextArea) PanelFixture.find(panel, "customQuotes");
            text.setText("my next video bit");
            assertEquals("original", config.customQuotes());
            panel.refresh("chatFrequency");
            assertEquals("my next video bit", text.getText());
            config.values.put("customQuotes", "external edit");
            panel.refresh("customQuotes");
            assertEquals("my next video bit", text.getText());
            PanelFixture.button(panel, "Revert").doClick();
            assertEquals("external edit", text.getText());
            config.values.put("customQuotes", "another external edit");
            panel.refresh("customQuotes");
            assertEquals("Clean editors follow config changes", "another external edit", text.getText());
            text.setText("{player} nice {gear}\nhello youtube");
            PanelFixture.button(panel, "Save lines").doClick();
            assertEquals(text.getText(), config.customQuotes());
            assertFalse(PanelFixture.button(panel, "Save lines").isEnabled());
            text.setCaretPosition(text.getText().length());
            PanelFixture.button(panel, "{target}").doClick();
            assertTrue(text.getText().endsWith("{target}"));
            assertTrue(PanelFixture.button(panel, "Save lines").isEnabled());
        });
    }
}

package com.celebritymode.ui;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;
import javax.swing.*;
import net.runelite.client.ui.laf.RuneLiteLAF;

/** Renders the actual Swing panel at RuneLite's sidebar width without logging into the game. */
public final class SidebarPreview {
    private SidebarPreview() {}

    public static void main(String[] args) throws Exception {
        UIManager.setLookAndFeel(new RuneLiteLAF());
        SwingUtilities.invokeAndWait(() -> {
            try {
                PanelFixture config = new PanelFixture();
                config.values.put("customQuotes", "{player} can we get a bank tour\nall this gear just to forget a teleport\n{target} has no idea this is going on youtube");
                CelebrityModePanel panel = new CelebrityModePanel(config, config::write);
                String[] pages = {"Crowd", "Dialogue", "Extras"};
                BufferedImage[] images = new BufferedImage[pages.length];
                int height = 0;
                for (int i = 0; i < pages.length; i++) {
                    PanelFixture.button(panel, pages[i]).doClick();
                    panel.setSize(225, panel.getPreferredSize().height);
                    layout(panel);
                    images[i] = new BufferedImage(450, panel.getHeight() * 2, BufferedImage.TYPE_INT_ARGB);
                    Graphics2D g = images[i].createGraphics();
                    g.scale(2, 2);
                    panel.printAll(g);
                    g.dispose();
                    height = Math.max(height, images[i].getHeight());
                }
                BufferedImage preview = new BufferedImage(1410, height + 40, BufferedImage.TYPE_INT_RGB);
                Graphics2D g = preview.createGraphics();
                g.setColor(new Color(23, 26, 30));
                g.fillRect(0, 0, preview.getWidth(), preview.getHeight());
                for (int i = 0; i < images.length; i++) g.drawImage(images[i], 10 + i * 470, 20, null);
                g.dispose();
                File output = new File("build/sidebar-preview.png");
                ImageIO.write(preview, "png", output);
                ImageIO.write(CelebrityModeIcon.create(64), "png", new File("build/sidebar-icon.png"));
                System.out.println(output.getAbsolutePath());
            } catch (Exception ex) {
                throw new IllegalStateException(ex);
            }
        });
    }

    private static void layout(Container container) {
        container.doLayout();
        for (Component child : container.getComponents()) if (child instanceof Container) layout((Container) child);
    }
}

package com.celebritymode.ui;

import com.celebritymode.CelebrityModeConfig;
import com.celebritymode.chat.*;
