import com.celebritymode.movement.FormationStyle;
import com.celebritymode.pm.TrafficIntensity;
import java.awt.*;
import java.util.*;
import javax.swing.*;

final class PanelFixture implements CelebrityModeConfig {
    final Map<String, Object> values = new HashMap<>();
    int writes;
    void write(String key, Object value) { values.put(key, value); writes++; }
    public int crowdSize() { return (Integer) values.getOrDefault("crowdSize", 8); }
    public boolean showCrowd() { return (Boolean) values.getOrDefault("showCrowd", true); }
    public ArrivalPace arrivalPace() { return (ArrivalPace) values.getOrDefault("arrivalPace", ArrivalPace.GRADUAL); }
    public FormationStyle formationStyle() { return (FormationStyle) values.getOrDefault("formationStyle", FormationStyle.ENTOURAGE); }
    public int maxSpread() { return (Integer) values.getOrDefault("maxSpread", 2); }
    public boolean respectPersonalSpace() { return (Boolean) values.getOrDefault("respectPersonalSpace", true); }
    public FanGearTier crowdGearTier() { return (FanGearTier) values.getOrDefault("crowdGearTier", FanGearTier.MIXED); }
    public boolean showFanNames() { return (Boolean) values.getOrDefault("showFanNames", false); }
    public ChatFrequency chatFrequency() { return (ChatFrequency) values.getOrDefault("chatFrequency", ChatFrequency.SPAM); }
    public CustomQuoteMode customQuoteMode() { return (CustomQuoteMode) values.getOrDefault("customQuoteMode", CustomQuoteMode.MIXED); }
    public String customQuotes() { return (String) values.getOrDefault("customQuotes", ""); }
    public boolean reactToEvents() { return (Boolean) values.getOrDefault("reactToEvents", true); }
    public boolean enableFanPms() { return (Boolean) values.getOrDefault("enableFanPms", false); }
    public TrafficIntensity pmTrafficIntensity() { return (TrafficIntensity) values.getOrDefault("pmTrafficIntensity", TrafficIntensity.RELAXED); }
    public boolean pmNotificationSound() { return (Boolean) values.getOrDefault("pmNotificationSound", false); }
    public boolean debugMode() { return (Boolean) values.getOrDefault("debugMode", false); }

    static Component find(Container parent, String name) {
        for (Component child : parent.getComponents()) {
            if (name.equals(child.getName())) return child;
            if (child instanceof Container) {
                Component found = find((Container) child, name);
                if (found != null) return found;
            }
        }
        return null;
    }

    static JButton button(Container parent, String text) {
        for (Component child : parent.getComponents()) {
            if (child instanceof JButton && text.equals(((JButton) child).getText())) return (JButton) child;
            if (child instanceof Container) {
                JButton found = button((Container) child, text);
                if (found != null) return found;
            }
        }
        return null;
    }
}

package com.celebritymode;

import com.celebritymode.appearance.*;

import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.gameval.AnimationID;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.externalplugins.ExternalPluginManager;

import org.slf4j.LoggerFactory;

import java.util.Random;

/** Developer launcher, as used by the official Plugin Hub template. */
public class CelebrityModePluginTest {
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        ExternalPluginManager.loadBuiltin(CelebrityModePlugin.class);
        RuneLite.main(args);
        if (Boolean.getBoolean("celebritymode.verifyModels")) verifyCacheModels();
    }

    /**
     * Opt-in developer check against the actual injected client/cache, even at the login screen.
     */
    private static void verifyCacheModels() {
        Client client = RuneLite.getInjector().getInstance(Client.class);
        ClientThread thread = RuneLite.getInjector().getInstance(ClientThread.class);
        FanModelFactory models = new FanModelFactory(client);
        FanAppearanceFactory appearances = new FanAppearanceFactory(new Random(17), models);
        int[] animationIds = {
            AnimationID.HUMAN_READY,
            AnimationID.HUMAN_WALK_F,
            AnimationID.HUMAN_RUNNING,
            AnimationID.EMOTE_WAVE,
            AnimationID.EMOTE_CHEER,
            AnimationID.SLAYER_ABYSSAL_WHIP_WALK,
            AnimationID.SLAYER_ABYSSAL_WHIP_RUN,
            AnimationID.HUMAN_STAFFREADY
        };
        int[] next = {0};
        int[] attempts = {0};
        FanAppearance[] pending = {null};
        thread.invokeLater(
                () -> {
                    if (client.getGameState() != net.runelite.api.GameState.LOGIN_SCREEN
                            && client.getGameState() != net.runelite.api.GameState.LOGGED_IN)
                        return false;
                    if (++attempts[0] > 1000) {
                        LoggerFactory.getLogger(CelebrityModePluginTest.class)
                                .error("Cache model verification timed out");
                        return true;
                    }
                    try {
                        appearances.advanceCatalog();
                        if (!appearances.getCatalog().complete()) return false;
                        FanGearTier tier = FanGearTier.values()[next[0]];
                        if (pending[0] == null)
                            pending[0] = appearances.createAppearance(next[0], tier);
                        FanAppearance appearance = pending[0];
                        if (tier != FanGearTier.DEFAULT_BOB && appearance.equipment.length == 0)
                            throw new IllegalStateException(
                                    "Empty equipment catalogue for " + tier);
                        Model model = models.createModel(appearance);
                        if (model == null || model.getVerticesCount() == 0) return false;
                        for (int id : animationIds) {
                            Model posed = new AnimationController(client, id).animate(model);
                            if (posed == null || posed.getVerticesCount() == 0) return false;
                        }
                        LoggerFactory.getLogger(CelebrityModePluginTest.class)
                                .info(
                                        "Cache model verification passed: {} ({} vertices, {}"
                                            + " animation sequences; {} wardrobe items; equipment"
                                            + " {})",
                                        tier,
                                        model.getVerticesCount(),
                                        animationIds.length,
                                        appearances.getCatalog().size(),
                                        java.util.Arrays.toString(appearance.equipment));
                        pending[0] = null;
                        return ++next[0] == FanGearTier.values().length;
                    } catch (RuntimeException ex) {
                        if (attempts[0] % 30 == 0)
                            LoggerFactory.getLogger(CelebrityModePluginTest.class)
                                    .debug("Waiting for cache model verification resources", ex);
                        return false;
                    }
                });
    }
}

