package com.celebritymode.appearance;

import static org.junit.Assert.*;

import com.celebritymode.TestScene;

import org.junit.Test;

import java.io.*;
import java.util.*;

public class EquipmentCatalogTest {
    private byte[] definition(
            String name, int slot, boolean members, boolean twoHanded, boolean placeholder)
            throws Exception {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        DataOutputStream out = new DataOutputStream(bytes);
        out.writeByte(2);
        out.writeBytes(name);
        out.writeByte(0);
        out.writeByte(13);
        out.writeByte(slot);
        out.writeByte(23);
        out.writeShort(100);
        out.writeByte(0);
        out.writeByte(35);
        out.writeBytes(slot == 3 ? "Wield" : "Wear");
        out.writeByte(0);
        if (members) out.writeByte(16);
        if (twoHanded) {
            out.writeByte(14);
            out.writeByte(5);
        }
        if (placeholder) {
            out.writeByte(149);
            out.writeShort(1);
        }
        out.writeByte(0);
        return bytes.toByteArray();
    }

    @Test
    public void scansBoundedCacheDefinitionsAndMatchesFamilies() throws Exception {
        TestScene scene = new TestScene();
        for (int family = 0; family < 30; family++)
            for (int slot : new int[] {0, 4, 7, 3, 5}) {
                int id = 22000 + family * 10 + slot;
                scene.itemDefinitions.put(
                        id,
                        definition(
                                "Set" + family + " " + (slot == 3 ? "staff" : "piece"),
                                slot,
                                true,
                                slot == 3,
                                false));
            }
        scene.itemDefinitions.put(1117, definition("Bronze platebody", 4, false, false, false));
        scene.itemDefinitions.put(9998, definition("Broken armour", 4, true, false, false));
        scene.itemDefinitions.put(9999, definition("Placeholder armour", 4, true, false, true));
        FanModelFactory models = new FanModelFactory(scene.client);
        EquipmentCatalog catalog = new EquipmentCatalog(models);
        catalog.advance(7);
        assertTrue(catalog.size() <= 7);
        assertFalse(catalog.complete());
        for (int i = 0; i < 40; i++) catalog.advance(7);
        assertTrue(catalog.complete());
        assertEquals(151, catalog.size());
        Random random = new Random(42);
        Set<Integer> bodies = new HashSet<>();
        for (int i = 0; i < 100; i++) {
            EquipmentCatalog.Item body = catalog.choose(4, FanGearTier.MODERN_GEAR, null, random);
            assertNotNull(body);
            assertTrue(body.id >= 20000);
            bodies.add(body.id);
            EquipmentCatalog.Item helm =
                    catalog.choose(0, FanGearTier.MODERN_GEAR, body.family, random);
            assertEquals(body.family, helm.family);
        }
        assertTrue(bodies.size() > 20);
        assertEquals(1117, catalog.choose(4, FanGearTier.BRONZE_NOOB, null, random).id);
        catalog.clear();
        assertEquals(0, catalog.size());
        assertFalse(catalog.complete());
    }

    @Test
    public void randomizedOutfitsSuppressShieldsForTwoHandedWeapons() throws Exception {
        TestScene scene = new TestScene();
        for (int set = 0; set < 50; set++)
            for (int slot : new int[] {0, 4, 7, 3, 5, 9, 10, 1})
                scene.itemDefinitions.put(
                        24000 + set * 12 + slot,
                        definition(
                                "Gear" + set + " " + (slot == 3 ? "bow" : "piece"),
                                slot,
                                true,
                                slot == 3,
                                false));
        FanModelFactory models = new FanModelFactory(scene.client);
        FanAppearanceFactory factory = new FanAppearanceFactory(new Random(3), models);
        for (int i = 0; i < 4; i++) factory.advanceCatalog();
        Set<String> outfits = new HashSet<>();
        for (int i = 0; i < 50; i++) {
            FanAppearance appearance = factory.createAppearance(i, FanGearTier.MODERN_GEAR);
            assertTrue(appearance.equipment.length >= 5);
            assertTrue(appearance.weaponName.contains("bow"));
            for (int id : appearance.equipment) assertNotEquals(5, (id - 24000) % 12);
            outfits.add(Arrays.toString(appearance.equipment));
            assertNotNull(models.createModel(appearance));
        }
        assertTrue(outfits.size() > 40);
    }
}

package com.celebritymode.pm;

import static org.junit.Assert.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

public class FanMessageSchedulerTest {
    @Test
    public void poissonDelaysMatchEveryRateAndIncludeClumpsAndLulls() {
        for (TrafficIntensity intensity : TrafficIntensity.values()) {
            Random random = new Random(83);
            double total = 0;
            long min = Long.MAX_VALUE, max = 0;
            for (int i = 0; i < 100000; i++) {
                long delay = FanMessageScheduler.nextDelayNanos(random, intensity);
                assertTrue(delay > 0);
                total += delay;
                min = Math.min(min, delay);
                max = Math.max(max, delay);
            }
            double mean = total / 100000;
            double expected = (double) TimeUnit.MINUTES.toNanos(1) / intensity.getMessagesPerMinute();
            assertEquals(expected, mean, expected * 0.02);
            assertTrue(min < expected / 20);
            assertTrue(max > expected * 6);
        }
    }

    @Test
    public void producerBufferDispatchAndStaleMessageWorkAreBounded() {
        ManualTimer timer = new ManualTimer();
        FanMessageScheduler scheduler = new FanMessageScheduler(new Random(3), () -> timer.now, () -> timer);
        scheduler.configure(true, TrafficIntensity.PEAK_WORLD_RECORD, "Hero");
        for (int i = 0; i < 300; i++) timer.runNext();
        assertEquals(32, scheduler.getPendingCount());
        assertEquals(268, scheduler.getDroppedCount());
        // The client missed all these messages, so don't replay the old inbox.
        assertTrue(scheduler.drain().isEmpty());
        assertEquals(0, scheduler.getPendingCount());
        for (int i = 0; i < 20; i++) timer.runNext();
        int sent = 0;
        for (int i = 0; i < 20; i++) {
            List<FanMessage> batch = scheduler.drain();
            assertTrue(batch.size() <= 2);
            sent += batch.size();
        }
        assertEquals(12, sent);
        timer.now += TimeUnit.SECONDS.toNanos(1);
        assertFalse(scheduler.drain().isEmpty());
        scheduler.shutdown();
        assertEquals(0, scheduler.getPendingCount());
        assertTrue(timer.isShutdown());
        assertTrue(scheduler.drain().isEmpty());
    }

    @Test
    public void cancelledOldCallbacksCannotProduceAfterDisableOrRestart() {
        List<ManualTimer> timers = new ArrayList<>();
        FanMessageScheduler scheduler = new FanMessageScheduler(new Random(2),
                () -> timers.get(timers.size() - 1).now, () -> {
                    ManualTimer timer = new ManualTimer();
                    timers.add(timer);
                    return timer;
                });
        scheduler.configure(true, TrafficIntensity.RELAXED, "Hero");
        Runnable stale = timers.get(0).nextCallback();
        timers.get(0).runNext();
        scheduler.configure(false, TrafficIntensity.RELAXED, "Hero");
        stale.run(); // Simulate a callback that was already entering its synchronized block.
        assertEquals(0, scheduler.getPendingCount());
        scheduler.configure(true, TrafficIntensity.STREAMER, "Hero");
        stale.run();
        assertEquals(0, scheduler.getPendingCount());
        ManualTimer timer = timers.get(1);
        for (int i = 0; i < 40; i++) scheduler.configure(true, TrafficIntensity.STREAMER, "New Name");
        assertEquals("Name refresh doesn't restart worker", 2, timers.size());
        assertEquals("Only one timer is outstanding", 1, timer.tasks.size());
        timer.runNext();
        assertEquals(1, scheduler.getPendingCount());
        scheduler.shutdown();
    }
}

package com.celebritymode.pm;

import java.util.*;
import java.util.concurrent.*;

/** Deterministic worker clock: no sleeps, real threads, or wall-clock-dependent assertions. */
final class ManualTimer extends AbstractExecutorService implements ScheduledExecutorService {
    long now;
    private boolean shutdown;
    final PriorityQueue<Task> tasks = new PriorityQueue<>();

    Runnable nextCallback() { return tasks.element().callback; }

    void runNext() {
        Task task = tasks.remove();
        now = Math.max(now, task.deadline);
        task.run();
    }

    @Override
    public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit) {
        if (shutdown) throw new RejectedExecutionException();
        Task task = new Task(command, now + unit.toNanos(delay));
        tasks.add(task);
        return task;
    }

    private final class Task extends FutureTask<Void> implements ScheduledFuture<Void> {
        private final Runnable callback;
        private final long deadline;
        Task(Runnable callback, long deadline) {
            super(callback, null);
            this.callback = callback;
            this.deadline = deadline;
        }
        public long getDelay(TimeUnit unit) { return unit.convert(deadline - now, TimeUnit.NANOSECONDS); }
        public int compareTo(Delayed other) { return Long.compare(deadline, ((Task) other).deadline); }
    }

    public void shutdown() { shutdown = true; tasks.clear(); }
    public List<Runnable> shutdownNow() { shutdown(); return Collections.emptyList(); }
    public boolean isShutdown() { return shutdown; }
    public boolean isTerminated() { return shutdown; }
    public boolean awaitTermination(long timeout, TimeUnit unit) { return shutdown; }
    public void execute(Runnable runnable) { schedule(runnable, 0, TimeUnit.NANOSECONDS); }
    public <V> ScheduledFuture<V> schedule(Callable<V> callable, long delay, TimeUnit unit) { throw new UnsupportedOperationException(); }
    public ScheduledFuture<?> scheduleAtFixedRate(Runnable runnable, long initial, long period, TimeUnit unit) { throw new UnsupportedOperationException(); }
    public ScheduledFuture<?> scheduleWithFixedDelay(Runnable runnable, long initial, long delay, TimeUnit unit) { throw new UnsupportedOperationException(); }
}

