        assertNull("Native formatting must remain in charge", queued.getRuneLiteFormattedMessage());
        assertNull(queued.getSender());
        assertEquals("Native timestamp uses insertion time", 0, queued.getTimestamp());
    }

    @Test
    public void dispatchFlushesOnClientThreadAndThrottlesSound() {
        ManualTimer timer = new ManualTimer();
        FanMessageScheduler scheduler = new FanMessageScheduler(new Random(4), () -> timer.now, () -> timer);
        TestScene scene = new TestScene();
        Settings settings = new Settings();
        List<QueuedMessage> queued = new ArrayList<>(), delivered = new ArrayList<>();
        List<Integer> sounds = new ArrayList<>();
        FanPmEngine engine = new FanPmEngine(scene.client, settings, scheduler, queued::add,
                () -> { delivered.addAll(queued); queued.clear(); }, sounds::add, () -> timer.now);
        engine.startUp();
        engine.onClientTick();
        assertTrue(delivered.isEmpty());
        timer.runNext();
        engine.onClientTick();
        assertEquals(1, delivered.size());
        assertTrue("No PMs linger in the shared queue", queued.isEmpty());
        assertEquals(Collections.singletonList(SoundEffectID.UI_BOOP), sounds);
        for (int i = 0; i < 4; i++) timer.runNext();
        engine.onClientTick();
        assertEquals(1, sounds.size());
        timer.now += TimeUnit.SECONDS.toNanos(2);
        engine.onClientTick();
        assertEquals(2, sounds.size());
        settings.sound = false;
        for (int i = 0; i < 4; i++) timer.runNext();
        timer.now += TimeUnit.SECONDS.toNanos(2);
        engine.onClientTick();
        assertEquals(2, sounds.size());
        engine.shutDown();
        assertTrue(timer.isShutdown());
        int count = delivered.size();
        engine.onClientTick();
        assertEquals(count, delivered.size());
    }

    @Test
    public void loginLoadingAndConfigDisableCannotLeakMessages() {
        List<ManualTimer> timers = new ArrayList<>();
        FanMessageScheduler scheduler = new FanMessageScheduler(new Random(6),
                () -> timers.get(timers.size() - 1).now, () -> {
                    ManualTimer timer = new ManualTimer(); timers.add(timer); return timer;
                });
        TestScene scene = new TestScene();
        scene.state = GameState.LOGIN_SCREEN;
        Settings settings = new Settings();
        List<QueuedMessage> messages = new ArrayList<>();
        FanPmEngine engine = new FanPmEngine(scene.client, settings, scheduler, messages::add,
                () -> {}, sound -> {}, () -> timers.isEmpty() ? 0 : timers.get(timers.size() - 1).now);
        engine.startUp();
        engine.onClientTick();
        assertTrue(timers.isEmpty());
        scene.state = GameState.LOGGED_IN;
        engine.onClientTick();
        timers.get(0).runNext();
        settings.enabled = false;
        engine.onClientTick();
        assertTrue(messages.isEmpty());
        assertEquals(0, scheduler.getPendingCount());
        assertTrue(timers.get(0).isShutdown());
        settings.enabled = true;
        engine.onClientTick();
        timers.get(1).runNext();
        engine.onGameStateChanged(GameState.LOADING);
        assertEquals(0, scheduler.getPendingCount());
        assertTrue(timers.get(1).isShutdown());
        scene.state = GameState.HOPPING;
        engine.onClientTick();
        assertTrue(messages.isEmpty());
        engine.shutDown();
    }
}

package com.celebritymode.pm;

import static org.junit.Assert.*;
import java.util.*;
import org.junit.Test;

public class FanDialogueGeneratorTest {
    @Test
    public void corpusHasVariedLegalNamesResolvedTokensAndWeightedTones() {
        FanDialogueGenerator generator = new FanDialogueGenerator();
        Random random = new Random(709);
        Set<String> names = new HashSet<>(), lines = new HashSet<>();
        EnumMap<FanMessage.Archetype, Integer> counts = new EnumMap<>(FanMessage.Archetype.class);
        for (int i = 0; i < 10000; i++) {
            FanMessage message = generator.generate(random, "Local Hero", i);
            assertTrue(message.getUsername(), message.getUsername().matches("[A-Za-z0-9 _]{1,12}"));
            assertFalse(message.getUsername().replace('_', ' ').equalsIgnoreCase("Local Hero"));
            assertFalse(message.getText().contains("{"));
            assertFalse(message.getText().contains("}"));
            assertTrue(message.getText().length() <= 160);
            assertEquals(i, message.getCreatedNanos());
            counts.merge(message.getArchetype(), 1, Integer::sum);
            names.add(message.getUsername());
            lines.add(message.getText());
        }
        assertTrue(names.size() > 2000);
        assertTrue(lines.size() > 1000);
        assertTrue(counts.get(FanMessage.Archetype.HYPE) > 4200 && counts.get(FanMessage.Archetype.HYPE) < 4800);
        assertTrue(counts.get(FanMessage.Archetype.FRIEND) > 2200 && counts.get(FanMessage.Archetype.FRIEND) < 2800);
        assertTrue(counts.get(FanMessage.Archetype.REQUEST) > 1700 && counts.get(FanMessage.Archetype.REQUEST) < 2300);
        assertTrue(counts.get(FanMessage.Archetype.SKEPTIC) > 700 && counts.get(FanMessage.Archetype.SKEPTIC) < 1300);
    }

    @Test
    public void nestedTokensAreExpandedAndReplacementMetacharactersStayLiteral() {
        Map<String, String> slots = new HashMap<>();
        slots.put("request", "join {clan_name}");
        slots.put("clan_name", "$1 \\ club");
        assertEquals("yo join $1 \\ club", FanDialogueGenerator.expand("yo {request}", slots));
        slots.put("loop", "{loop}");
        try {
            FanDialogueGenerator.expand("{loop}", slots);
            fail("Cyclic templates must be bounded");
        } catch (IllegalArgumentException expected) {
            assertTrue(expected.getMessage().contains("Cyclic"));
        }
    }

    @Test
    public void hostileNameMarkupDoesNotEnterMessages() {
        FanDialogueGenerator generator = new FanDialogueGenerator();
        Random random = new Random(1);
        for (int i = 0; i < 100; i++) {
            String text = generator.generate(random, "<img=1>Hero<col=ff0000>{boss}", i).getText();
            assertFalse(text.contains("<img"));
            assertFalse(text.contains("<col"));
            assertFalse(text.contains("{"));
        }
    }
}

