            for (RuneLiteObject object : old) assertFalse(object.isActive());
            scene.populate();
            assertEquals(8, scene.active.size());
            for (FanEntity fan : scene.manager.getFans())
                assertEquals(scene.viewId, fan.renderLocation.getWorldView());
