        scene.state = GameState.HOPPING;
        scene.manager.onClientTick();
        assertTrue(scene.active.isEmpty());
        for (FanEntity fan : scene.manager.getFans()) {
            assertNull(fan.renderLocation);
            assertNull(fan.movementPath);
