        scene.state = GameState.LOGGED_IN;
        scene.tick();
        assertTrue(scene.active.isEmpty());
        scene.populate();
        assertEquals(8, scene.active.size());
        scene.manager.onGameTick(null);
        assertTrue(scene.active.isEmpty());
        scene.populate();
        assertEquals(8, scene.active.size());
