/** Client-thread-only observations. Login snapshots establish baselines, not fake XP gains. */
// RuneLite retains the deprecated OVERALL pseudo-skill in values(); exclude it from XP snapshots.
@SuppressWarnings("deprecation")
public final class FanActivityTracker {
    private final EnumMap<Skill, Integer> experience = new EnumMap<>(Skill.class);
    private Skill recentSkill;
    private int xpTick = Integer.MIN_VALUE,
            attackTick = Integer.MIN_VALUE,
            gearTick = Integer.MIN_VALUE;
    private int gain;
    private String previousGear;

    public void experience(Skill skill, int xp, int tick) {
        if (skill == Skill.OVERALL) return;
        Integer previous = experience.put(skill, xp);
        if (previous == null || xp <= previous || skill == Skill.HITPOINTS) return;
        recentSkill = skill;
        gain = xp - previous;
        xpTick = tick;
    }

    public void menu(String option, int tick) {
        if ("Attack".equalsIgnoreCase(FanChatContext.clean(option))) attackTick = tick;
    }

    public FanChatContext observe(
            Client client, Player player, String gear, boolean moved, boolean running, int tick) {
        for (Skill skill : Skill.values())
            if (skill != Skill.OVERALL)
                experience.putIfAbsent(skill, client.getSkillExperience(skill));
        String cleanGear = FanChatContext.clean(gear);
        if (previousGear != null && !previousGear.equals(cleanGear)) gearTick = tick;
        previousGear = cleanGear;
        boolean recentXp = (long) tick - xpTick <= 10;
        Skill skill = recentXp ? recentSkill : null;
        Actor target = player.getInteracting();
        boolean fighting =
                target != null
                        && ((long) tick - attackTick <= 8
                                || recentXp && combat(skill)
                                || target.getCombatLevel() > 0
                                        && target.getHealthRatio() >= 0
                                        && player.getAnimation() >= 0);
        Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        FanChatContext.Activity activity =
                bank != null && !bank.isHidden()
                        ? FanChatContext.Activity.BANKING
                        : fighting
                                ? FanChatContext.Activity.COMBAT
                                : recentXp
                                                && (!moved || skill == Skill.AGILITY)
                                                && (!combat(skill) || target == null)
                                        ? FanChatContext.Activity.SKILLING
                                        : moved
                                                ? running
                                                        ? FanChatContext.Activity.RUNNING
                                                        : FanChatContext.Activity.WALKING
                                                : FanChatContext.Activity.IDLE;
        int realHp = client.getRealSkillLevel(Skill.HITPOINTS);
        boolean lowHealth =
                fighting
                        && realHp > 0
                        && client.getBoostedSkillLevel(Skill.HITPOINTS) * 100 / realHp <= 30;
        return new FanChatContext(
                player.getName(),
                cleanGear,
                fighting ? target.getName() : "",
                activity,
                skill,
                skill == null ? 0 : client.getRealSkillLevel(skill),
                recentXp ? gain : 0,
                lowHealth,
                (long) tick - gearTick <= 8 && !cleanGear.isEmpty());
    }

    private static boolean combat(Skill skill) {
        return skill == Skill.ATTACK
                || skill == Skill.STRENGTH
                || skill == Skill.DEFENCE
                || skill == Skill.RANGED
                || skill == Skill.MAGIC
                || skill == Skill.HITPOINTS;
    }

    public void clear() {
        experience.clear();
        recentSkill = null;
        gain = 0;
        previousGear = null;
        xpTick = attackTick = gearTick = Integer.MIN_VALUE;
    }
}

package com.celebritymode.chat;

import net.runelite.api.Skill;

/** Observations about the local character, never guesses about loot or achievements. */
public final class FanChatContext {
    public enum Activity {
        IDLE,
        WALKING,
        RUNNING,
        BANKING,
        COMBAT,
        SKILLING
    }

    public final String player, gear, target;
    public final Activity activity;
    public final Skill skill;
    public final int level, gainedXp;
    public final boolean lowHealth, gearChanged;

    public FanChatContext(
            String player,
            String gear,
            String target,
            Activity activity,
            Skill skill,
            int level,
            int gainedXp,
            boolean lowHealth,
            boolean gearChanged) {
        this.player = clean(player);
        this.gear = clean(gear);
        this.target = clean(target);
        this.activity = activity;
        this.skill = skill;
        this.level = level;
        this.gainedXp = gainedXp;
        this.lowHealth = lowHealth;
        this.gearChanged = gearChanged;
    }

    public static FanChatContext idle(String name, String gear) {
        return new FanChatContext(name, gear, "", Activity.IDLE, null, 0, 0, false, false);
    }

    public static String clean(String value) {
        return value == null ? "" : value.replaceAll("<[^>]*>", "").replace('\u00a0', ' ').trim();
    }
}

package com.celebritymode.chat;

import com.celebritymode.fan.*;

import java.util.*;
import java.util.regex.Pattern;

/** One crowd scheduler, rather than thirty competing timers. */
public final class FanChatManager {
    private static final Pattern PUNCTUATION = Pattern.compile("[^a-z0-9 ]");
    private static final Pattern SPACES = Pattern.compile(" +");
    private final Random random;
    private ChatFrequency frequency = ChatFrequency.OFF;
    private FanChatContext context = FanChatContext.idle("", "");
    private final Deque<String> recentCrowd = new ArrayDeque<>();
    private final Map<FanEntity, Deque<String>> recentFans = new IdentityHashMap<>();
    private int nextTick = Integer.MAX_VALUE;
    private String lastQuote;
    private CustomQuoteMode mode = CustomQuoteMode.BUILT_IN_ONLY;
    private List<String> custom = Collections.emptyList();

    public FanChatManager(Random random) {
        this.random = random;
    }

    public void configure(ChatFrequency frequency, CustomQuoteMode mode, String custom, int tick) {
        this.frequency = frequency;
        this.mode = mode;
        List<String> parsed = FanQuoteLibrary.parse(custom);
        this.custom = parsed;

        nextTick =
                frequency == ChatFrequency.OFF ? Integer.MAX_VALUE : tick + frequency.delay(random);
    }

    public int getNextTick() {
        return nextTick;
    }

    public void tick(List<FanEntity> fans, int tick) {
        recentFans.keySet().retainAll(fans);
        for (FanEntity fan : fans) if (tick >= fan.overheadExpiryTick) fan.overheadText = null;
        if (frequency == ChatFrequency.OFF || tick < nextTick) return;
        nextTick = tick + frequency.delay(random);
        List<FanEntity> eligible = new ArrayList<>(fans.size());
        int visible = 0;
        for (FanEntity fan : fans) {
            if (!fan.isVisible()) continue;
            visible++;
            if (tick >= fan.nextChatTick
                    && (mode != CustomQuoteMode.CUSTOM_ONLY || !custom.isEmpty()))
                eligible.add(fan);
        }
        Collections.shuffle(eligible, random);
        int batch =
                frequency == ChatFrequency.LOW
                        ? 1
                        : frequency == ChatFrequency.NORMAL
                                ? Math.max(1, (visible + 2) / 3)
                                : Math.max(1, (2 * visible + 2) / 3);
        for (int i = 0; i < Math.min(batch, eligible.size()); i++) {
            FanEntity fan = eligible.get(i);
            say(fan, chooseFor(fan), tick);
            fan.nextChatTick =
                    tick
                            + (frequency == ChatFrequency.SPAM
                                    ? 1 + random.nextInt(2)
                                    : frequency == ChatFrequency.NORMAL
                                            ? 3 + random.nextInt(3)
                                            : 8 + random.nextInt(5));
        }
    }

    public void setContext(String name, String equipment) {
        setContext(FanChatContext.idle(name, equipment));
    }

    public void setContext(FanChatContext context) {
        this.context = context;
    }

    private String personalize(String quote) {
        if (quote == null) return null;
        String result =
                quote.replace("{player}", context.player.isEmpty() ? "you" : context.player)
                        .replace("{gear}", context.gear.isEmpty() ? "fit" : context.gear)
                        .replace("{target}", context.target.isEmpty() ? "opponent" : context.target)
                        .replace(
                                "{skill}",
                                context.skill == null ? "skill" : context.skill.getName())
                        .replace("{level}", Integer.toString(context.level));
        return result.substring(0, Math.min(100, result.length()));
    }

    public void level(List<FanEntity> fans, int tick, net.runelite.api.Skill skill, int level) {
        FanChatContext event =
                new FanChatContext(
                        context.player,
                        context.gear,
                        context.target,
                        context.activity,
                        skill,
                        level,
                        0,
                        false,
                        false);
        FanChatContext previous = context;
        context = event;
        try {
            react(
                    fans,
                    tick,
                    new String[] {
                        FanDialogueGenerator.level(event, random),
                        FanDialogueGenerator.level(event, random)
                    });
        } finally {
            context = previous;
        }
    }

    private static String signature(String line) {
        return SPACES.matcher(PUNCTUATION.matcher(line.toLowerCase(Locale.ENGLISH)).replaceAll(""))
                .replaceAll(" ")
                .trim();
    }

    private String chooseFor(FanEntity fan) {
        if (mode == CustomQuoteMode.CUSTOM_ONLY
                || (mode == CustomQuoteMode.MIXED && !custom.isEmpty() && random.nextInt(3) == 0))
            return choose(custom);
        String line = null;
        for (int attempt = 0; attempt < 24; attempt++) {
            line = FanDialogueGenerator.generate(random, fan.personality, context);
            String key = signature(line);
            if (!recentCrowd.contains(key)
                    && (recentFans.get(fan) == null || !recentFans.get(fan).contains(key))
                    && !line.equals(lastQuote)) break;
        }
        lastQuote = line;
        return line;
    }

    public String choose(List<String> pool) {
        if (pool == null || pool.isEmpty()) return null;
        List<String> candidates = new ArrayList<>();
        for (String q : pool) if (!personalize(q).equals(lastQuote)) candidates.add(personalize(q));
        String quote =
                candidates.isEmpty()
                        ? personalize(pool.get(0))
                        : candidates.get(random.nextInt(candidates.size()));
        lastQuote = quote;
        return quote;
    }

    public void react(List<FanEntity> fans, int tick, String[] quotes) {
        if (frequency == ChatFrequency.OFF || fans.isEmpty()) return;
        List<String> source = mode == CustomQuoteMode.CUSTOM_ONLY ? custom : Arrays.asList(quotes);
        if (source.isEmpty()) return;
        int start = random.nextInt(fans.size());
        for (int i = 0; i < Math.min(2, fans.size()); i++) {
            FanEntity fan = fans.get((start + i) % fans.size());
            if (fan.isVisible()) {
                say(fan, choose(source), tick);
                fan.nextChatTick = Math.max(fan.nextChatTick, tick + 3);
            }
        }
    }

    private void say(FanEntity fan, String quote, int tick) {
        if (quote != null) {
            String key = signature(quote);
            recentCrowd.addLast(key);
            if (recentCrowd.size() > 64) recentCrowd.removeFirst();
            Deque<String> personal = recentFans.computeIfAbsent(fan, ignored -> new ArrayDeque<>());
            personal.addLast(key);
            if (personal.size() > 12) personal.removeFirst();
            fan.overheadText = quote;
            fan.overheadExpiryTick = tick + 5 + random.nextInt(4);
        }
    }

    public void clear(List<FanEntity> fans) {
        for (FanEntity f : fans) {
            f.overheadText = null;
            f.nextChatTick = 0;
        }
        lastQuote = null;
        recentCrowd.clear();
        recentFans.clear();
        nextTick = Integer.MAX_VALUE;
    }
}

package com.celebritymode.chat;

public enum CustomQuoteMode {
    BUILT_IN_ONLY,
    CUSTOM_ONLY,
    MIXED
}

package com.celebritymode.chat;

import java.util.Random;

public enum ChatFrequency {
    OFF(0, 0),
    LOW(5, 10),
    NORMAL(1, 2),
    SPAM(1, 1);
    public final int minimumTicks, maximumTicks;

    ChatFrequency(int min, int max) {
        minimumTicks = min;
        maximumTicks = max;
    }

    public int delay(Random random) {
        return minimumTicks + random.nextInt(maximumTicks - minimumTicks + 1);
    }
}

package com.celebritymode.chat;

import com.celebritymode.fan.FanPersonality;

import java.util.*;

public final class FanQuoteLibrary {
    private FanQuoteLibrary() {}

    public static List<String> parse(String input) {
        if (input == null || input.trim().isEmpty()) return Collections.emptyList();
        String[] parts =
                input.split(input.contains("\n") || input.contains("\r") ? "\r\n|[\r\n]" : ",");
        List<String> result = new ArrayList<>();
        for (String s : parts) {
            String clean = s.replaceAll("<[^>]*>", "").trim();
            if (!clean.isEmpty()) result.add(clean.substring(0, Math.min(100, clean.length())));
            if (result.size() == 100) break;
        }
        return Collections.unmodifiableList(result);
    }

    public static List<String> quotes(FanPersonality personality) {
        switch (personality) {
            case BEGGAR:
                return Arrays.asList(
                        "can i have free stuff", "how rich are u", "drop party???", "buying gf");
            case MEMER:
                return Arrays.asList(
                        "reported", "LOOOOOOL", "wave2:flash:@@@@@@", "{player} is actually here");
            case SCREENSHOTTER:
                return Arrays.asList("OMG SCREENSHOT", "say hi youtube", "its actually him");
            case HYPEMAN:
                return Arrays.asList("OMG IT'S {player}", "huge fan", "no way");
            default:
                return Arrays.asList(
                        "omg", "nice cape", "follow me", "bro add me", "nice", "no way");
        }
    }

    public static List<String> pool(FanPersonality p, CustomQuoteMode mode, List<String> custom) {
        List<String> pool = new ArrayList<>();
        if (mode != CustomQuoteMode.CUSTOM_ONLY) pool.addAll(quotes(p));
        if (mode != CustomQuoteMode.BUILT_IN_ONLY) pool.addAll(custom);
        return pool;
    }
}

package com.celebritymode.chat;

import com.celebritymode.fan.FanPersonality;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Context-selected patterns composed with conversational fragments, rather than fixed quotes. */
public final class FanDialogueGenerator {
    private static final Map<String, List<String>> PATTERNS = load();
    private static final String[] GREETINGS = {
        "yo",
        "hey",
        "oh hey",
        "wait",
        "omg",
        "no way",
        "hold up",
        "ay",
        "look who it is",
        "well hello"
    };
    private static final String[] PRAISE = {
        "clean",
        "goated",
        "huge",
        "insane",
        "unreal",
        "actually sick",
        "looking good",
        "solid",
        "proper nice",
        "impressive",
        "a vibe",
        "next level"
    };
    private static final String[] REQUESTS = {
        "add me",
        "teach me your ways",
        "say hi to the cc",
        "raid with us",
        "join the clan",
        "share the secret",
        "give us a tip",
        "save me a spot",
        "show me your setup",
        "come on a boss trip"
    };
    private static final String[] ACTIVITIES = {
        "toa",
        "tob",
        "cox",
        "a boss trip",
        "a duo",
        "a quest",
        "a chill slayer trip",
        "a minigame",
        "a clan event",
        "some pvm",
        "a wildy trip"
    };
    private static final String[] GOALS = {
        "99",
        "pet",
        "gear upgrade",
        "diary",
        "collection log slot",
        "combat achievement",
        "quest",
        "skill milestone",
        "personal best",
        "cape"
    };
    private static final String[] SUPPLIES = {
        "staminas", "food", "teleports", "restores", "prayer pots", "runes", "bonds", "advice"
    };
    private static final String[] ENDINGS = {" lol", " haha", " pls", " :)", " fr", "", "", "", ""};

    private FanDialogueGenerator() {}

    public static String generate(
            Random random, FanPersonality personality, String name, String gear) {
        return generate(random, personality, FanChatContext.idle(name, gear));
    }

    public static String generate(
            Random random, FanPersonality personality, FanChatContext context) {
        String category;
        int roll = random.nextInt(100);
        if (context.lowHealth && roll < 20) category = "low_health";
        else if (context.gearChanged && roll < 30) category = "gear_change";
        else if (!context.gear.isEmpty() && roll >= 90) category = "gear";
        else if (roll < 65) {
            category = context.activity.name().toLowerCase(Locale.ENGLISH);
            if (context.activity == FanChatContext.Activity.SKILLING
                    && context.skill != null
                    && random.nextInt(3) != 0) {
                String specific = context.skill.name().toLowerCase(Locale.ENGLISH);
                if (PATTERNS.containsKey(specific)) category = specific;
            }
            if (context.activity == FanChatContext.Activity.COMBAT
                    && !context.target.isEmpty()
                    && random.nextBoolean()) category = "combat_target";
        } else
            category =
                    random.nextBoolean()
                            ? "social"
                            : personality.name().toLowerCase(Locale.ENGLISH);
        return line(category, context, random, true);
    }

    public static String level(FanChatContext context, Random random) {
        return line("level", context, random, false);
    }

    private static String line(
            String category, FanChatContext context, Random random, boolean decorate) {
        List<String> valid = new ArrayList<>();
        for (String pattern : PATTERNS.getOrDefault(category, PATTERNS.get("social"))) {
            if (pattern.contains("{level}") && context.level <= 0
                    || pattern.contains("{xp}") && context.gainedXp <= 0
                    || pattern.contains("{skill}") && context.skill == null) continue;
            valid.add(pattern);
        }
        if (valid.isEmpty()) valid = PATTERNS.get("social");
        String result =
                valid.get(random.nextInt(valid.size()))
                        .replace("{player}", context.player.isEmpty() ? "friend" : context.player)
                        .replace(
                                "{gear}",
                                context.gear.isEmpty()
                                        ? "fit"
                                        : context.gear.toLowerCase(Locale.ENGLISH))
                        .replace("{target}", context.target)
                        .replace(
                                "{skill}",
                                context.skill == null
                                        ? "skill"
                                        : context.skill.getName().toLowerCase(Locale.ENGLISH))
                        .replace("{level}", Integer.toString(context.level))
                        .replace("{xp}", Integer.toString(context.gainedXp))
                        .replace("{greeting}", pick(GREETINGS, random))
                        .replace("{praise}", pick(PRAISE, random))
                        .replace("{request}", pick(REQUESTS, random))
                        .replace("{activity}", pick(ACTIVITIES, random))
                        .replace("{goal}", pick(GOALS, random))
                        .replace("{supply}", pick(SUPPLIES, random));
        if (decorate && random.nextInt(7) == 0) result = pick(GREETINGS, random) + ", " + result;
        if (decorate && random.nextInt(5) == 0 && !result.endsWith("?"))
            result += pick(ENDINGS, random);
        if (decorate && random.nextInt(24) == 0) result = result.toUpperCase(Locale.ENGLISH);
        return result.substring(0, Math.min(100, result.length()));
    }

    private static String pick(String[] options, Random random) {
        return options[random.nextInt(options.length)];
    }

    private static Map<String, List<String>> load() {
        Map<String, List<String>> result = new HashMap<>();
        try (BufferedReader reader =
                new BufferedReader(
                        new InputStreamReader(
                                Objects.requireNonNull(
                                        FanDialogueGenerator.class.getResourceAsStream(
                                                "dialogue.txt")),
                                StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.isEmpty() || line.startsWith("#")) continue;
                String[] entry = line.split("\\|", 2);
                if (entry.length != 2) throw new IOException("Invalid dialogue pattern");
                result.computeIfAbsent(entry[0], key -> new ArrayList<>()).add(entry[1]);
            }
        } catch (IOException ex) {
            throw new IllegalStateException("Unable to load fan dialogue", ex);
        }
        return result;
    }
}

