        fit(navigation);
        add(navigation);
        add(Box.createVerticalStrut(12));
        pages.add(crowdPage());
        pages.add(dialoguePage());
        pages.add(extrasPage());
        add(body);
        add(Box.createVerticalStrut(12));
        add(hint("Only you see the fans. Your recording captures the audience."));
