package com.celebritymode.ui;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import javax.imageio.ImageIO;

/** The supplied crown artwork, shared by the toolbar and panel header. */
public final class CelebrityModeIcon {
    private static final BufferedImage SOURCE = load();

    private CelebrityModeIcon() {}

    private static BufferedImage load() {
        try (InputStream stream = CelebrityModeIcon.class.getResourceAsStream("icon.png")) {
            if (stream == null) throw new IllegalStateException("Missing Celebrity Mode icon resource");
            BufferedImage image = ImageIO.read(stream);
            if (image == null) throw new IllegalStateException("Invalid Celebrity Mode icon resource");
            return image;
        } catch (IOException ex) {
            throw new IllegalStateException("Unable to load Celebrity Mode icon", ex);
        }
    }

    public static BufferedImage create(int size) {
        BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try {
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
            g.drawImage(SOURCE, 0, 0, size, size, null);
        } finally {
            g.dispose();
        }
        return image;
    }
}

package com.celebritymode.appearance;

import java.util.*;
import java.util.Random;

import javax.inject.*;

@Singleton
public final class FanAppearanceFactory {
    private final Random random;
    private final FanModelFactory models;
    private final EquipmentCatalog catalog;
    // Male body palettes in the cache's packed HSL color space, applied before equipment.
    private static final short[][] COLORS = {
        {6798, 8741, 25238, 4626, 4550, 5681},
        {8741, 12, 4626, 4550, 5681, 25238},
        {25238, 8741, 12, 4626, 4550, 5681},
        {4626, 12, 4550, 5681, 8741},
        {4550, 4510, 4537, 5673, 5681}
    };

    @Inject
    public FanAppearanceFactory(Random random, FanModelFactory models) {
        this.random = random;
        this.models = models;
        catalog = new EquipmentCatalog(models);
    }

    public FanAppearance createAppearance(int index, FanGearTier requested) {
        FanGearTier tier = requested == FanGearTier.MIXED ? mixedTier() : requested;
        int[] kits = new int[7];
        for (int part = 0; part < 7; part++)
            kits[part] = models.chooseKit(part, random, tier == FanGearTier.DEFAULT_BOB);
        short[] colors = new short[5];
        for (int i = 0; i < colors.length; i++)
            colors[i] = COLORS[i][random.nextInt(COLORS[i].length)];
        // Bounded scanning samples across the whole cache, so modern items appear immediately.
        catalog.advance(256);
        List<EquipmentCatalog.Item> chosen = new ArrayList<>();
        EquipmentCatalog.Item body = catalog.choose(4, tier, null, random);
        if (body != null) chosen.add(body);
        String affinity = body == null ? null : body.family;
        for (int slot : new int[] {0, 7, 10, 9, 1, 2, 3}) {
            if ((slot == 2 || slot == 0) && random.nextInt(5) == 0) continue;
            EquipmentCatalog.Item item =
                    catalog.choose(
                            slot,
                            tier,
                            tier == FanGearTier.RANDOM_FASHIONSCAPE
                                            || slot == 3
                                            || slot == 1
                                            || slot == 2
                                    ? null
                                    : affinity,
                            random);
            if (item != null) chosen.add(item);
        }
        EquipmentCatalog.Item weapon = null;
        for (EquipmentCatalog.Item item : chosen) if (item.slot == 3) weapon = item;
        if (weapon == null || !weapon.twoHanded) {
            EquipmentCatalog.Item shield = catalog.choose(5, tier, null, random);
            if (shield != null) chosen.add(shield);
        }
        int[] equipment = chosen.stream().mapToInt(item -> item.id).toArray();
        String weaponName = weapon == null ? "" : weapon.name;
        return new FanAppearance(kits, equipment, colors, tier, weaponName);
    }

    private FanGearTier mixedTier() {
        int roll = random.nextInt(100);
        return roll < 5
                ? FanGearTier.DEFAULT_BOB
                : roll < 10
                        ? FanGearTier.BRONZE_NOOB
                        : roll < 20
                                ? FanGearTier.F2P_WARRIOR
                                : roll < 40
                                        ? FanGearTier.MIDGAME_WARRIOR
                                        : roll < 65
                                                ? FanGearTier.RANDOM_FASHIONSCAPE
                                                : FanGearTier.MODERN_GEAR;
    }

    public void advanceCatalog() {
        catalog.advance(256);
    }

    public EquipmentCatalog getCatalog() {
        return catalog;
    }

    public void clear() {
        catalog.clear();
    }
}

package com.celebritymode.appearance;

import net.runelite.api.*;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.nio.ByteBuffer;
import java.util.*;

import javax.inject.*;

/**
 * Public cache access only. Decodes IDK (archive 3) and OBJ (archive 10) worn meshes. Unknown
 * opcodes fail closed, rather than rendering inventory meshes as people. Cache definitions follow
 * RuneLite's KitLoader / ItemLoader format.
 */
@Singleton
public final class FanModelFactory {
    private static final Logger log = LoggerFactory.getLogger(FanModelFactory.class);
    private static final short[] BODY_COLORS = {6798, 8741, 25238, 4626, 4550};
    private final Client client;
    private final Map<Integer, Definition> kits = new LinkedHashMap<>(), items = new HashMap<>();

    @Inject
    public FanModelFactory(Client client) {
        this.client = client;
    }

    public int chooseKit(int part, Random random, boolean defaultBob) {
        if (kits.isEmpty()) {
            int[] ids = client.getIndexConfig().getFileIds(3);
            if (ids != null)
                for (int id : ids) {
                    byte[] data = client.getIndexConfig().loadData(3, id);
                    if (data == null) continue;
                    try {
                        Definition d = decode(data, true);
                        if (!d.hidden && d.part >= 0 && d.part < 7) kits.put(id, d);
                    } catch (IllegalArgumentException ex) {
                        log.debug("Skipping unsupported identity kit {}", id);
                    }
                }
        }
        List<Integer> candidates = new ArrayList<>();
        for (Map.Entry<Integer, Definition> e : kits.entrySet())
            if (e.getValue().part == part) candidates.add(e.getKey());
        if (candidates.isEmpty()) {
            kits.clear();
            throw new IllegalStateException("Body kits not available yet: " + part);
        }
        return candidates.get(defaultBob ? 0 : random.nextInt(candidates.size()));
    }

    public Model createModel(FanAppearance appearance) {
        try {
            return assemble(appearance, true);
        } catch (RuntimeException ex) {
            if (ex instanceof CacheUnavailable) throw ex;
            log.debug(
                    "Could not assemble {} outfit, falling back to body kits", appearance.tier, ex);
            return assemble(appearance, false);
        }
    }

    private Model assemble(FanAppearance appearance, boolean equipped) {
        List<ModelData> equipment = new ArrayList<>();
        boolean[] hidden = new boolean[7];
        if (equipped)
            for (int id : appearance.equipment) {
                Definition item = items.get(id);
                if (item == null) {
                    byte[] data = client.getIndexConfig().loadData(10, id);
                    if (data == null) throw new CacheUnavailable("Item unavailable: " + id);
                    item = decode(data, false);
                    items.put(id, item);
                }
                equipment.add(mesh(item));
                // Cache wear-position tags identify covered body kits, including arms/beards.
                int[] partSlots = {11, 8, 4, 6, 9, 7, 10};
                for (int part = 0; part < partSlots.length; part++)
                    if (item.slot == partSlots[part]
                            || item.wear2 == partSlots[part]
                            || item.wear3 == partSlots[part]) hidden[part] = true;
                // A head item replaces the hair/head kit; beard coverage follows cache tags.
                if (item.slot == 0) {
                    hidden[0] = true;
                }
                if (item.slot == 4) {
                    hidden[2] = true;
                    if (item.wear2 == 6) hidden[3] = true;
                }
                if (item.slot == 7) hidden[5] = true;
                if (item.slot == 9) hidden[4] = true;
                if (item.slot == 10) hidden[6] = true;
            }
        List<ModelData> body = new ArrayList<>();
        for (int part = 0; part < 7; part++)
            if (!hidden[part]) {
                Definition kit = kits.get(appearance.kits[part]);
                if (kit == null) throw new IllegalStateException("Missing body kit");
                body.add(mesh(kit));
            }
        if (!body.isEmpty()) {
            ModelData skin = client.mergeModels(body.toArray(new ModelData[0])).cloneColors();
            recolorBody(skin.getFaceColors(), appearance.colors);
            equipment.add(skin);
        }
        return client.mergeModels(equipment.toArray(new ModelData[0]))
                .light(64, 850, -30, -50, -30);
    }

    private ModelData mesh(Definition def) {
        List<ModelData> parts = new ArrayList<>();
        for (int id : def.models)
            if (id >= 0) {
                ModelData data = client.loadModelData(id);
                if (data == null) throw new CacheUnavailable("Missing mesh " + id);
                parts.add(data);
            }
        if (parts.isEmpty()) throw new IllegalStateException("No worn model");
        ModelData data = client.mergeModels(parts.toArray(new ModelData[0])).cloneColors();
        for (short[] pair : def.recolors) data.recolor(pair[0], pair[1]);
        // Untextured meshes have a null face-texture array. RuneLite's cloneTextures()
        // clones that array directly, so only call it when textures actually exist.
        if (!def.retextures.isEmpty() && data.getFaceTextures() != null) {
            data.cloneTextures();
            for (short[] pair : def.retextures) data.retexture(pair[0], pair[1]);
        }
        if (def.offset != 0) {
            data.cloneVertices().translate(0, def.offset, 0);
        }
        return data;
    }

    static void recolorBody(short[] faces, short[] colors) {
        for (int face = 0; face < faces.length; face++)
            for (int part = 0; part < BODY_COLORS.length; part++)
                if (faces[face] == BODY_COLORS[part]) {
                    faces[face] = colors[part];
                    break;
                }
    }

    private static final class CacheUnavailable extends IllegalStateException {
        private static final long serialVersionUID = 1L;

        CacheUnavailable(String message) {
            super(message);
        }
    }

    Definition readEquipment(int id) {
        byte[] data = client.getIndexConfig().loadData(10, id);
        return data == null ? null : decode(data, false);
    }

    int[] itemIds() {
        return client.getIndexConfig().getFileIds(10);
    }

    public void clear() {
        kits.clear();
        items.clear();
    }

    static final class Definition {
        int part = -1, slot = -1, wear2 = -1, wear3 = -1, offset;
        boolean hidden, members, tradeable;
        int noteTemplate = -1, placeholderTemplate = -1;
        String name = "";
        String[] actions = new String[5];
        int[] models = new int[] {-1, -1, -1};
        final List<short[]> recolors = new ArrayList<>(), retextures = new ArrayList<>();
    }

    static Definition decode(byte[] bytes, boolean kit) {
        try {
            ByteBuffer b = ByteBuffer.wrap(bytes);
            Definition d = new Definition();
            while (b.hasRemaining()) {
                int op = u8(b);
                if (op == 0) return d;
                if (kit) {
                    if (op == 1) d.part = u8(b);
                    else if (op == 2 || op == 5) {
                        d.models = new int[u8(b)];
                        for (int i = 0; i < d.models.length; i++)
                            d.models[i] = op == 2 ? u16(b) : b.getInt();
                    } else if (op == 3) d.hidden = true;
                    else if (op == 40 || op == 41) pairs(b, op == 40 ? d.recolors : d.retextures);
                    else if (op >= 60 && op < 70) u16(b);
                    else if (op >= 70 && op < 80) b.getInt();
                    else throw new IllegalArgumentException("Unknown kit opcode " + op);
                    continue;
                }
                if (op == 23 || op == 45) {
                    d.models[0] = op == 23 ? u16(b) : b.getInt();
                    d.offset = u8(b);
                } else if (op == 24 || op == 46) d.models[1] = op == 24 ? u16(b) : b.getInt();
                else if (op == 78 || op == 47) d.models[2] = op == 78 ? u16(b) : b.getInt();
                else if (op == 13) d.slot = u8(b);
                else if (op == 14) d.wear2 = u8(b);
                else if (op == 27) d.wear3 = u8(b);
                else if (op == 16) d.members = true;
                else if (op == 65) d.tradeable = true;
                else if (op == 98) d.noteTemplate = u16(b);
                else if (op == 149) d.placeholderTemplate = u16(b);
                else if (op == 2) d.name = string(b);
                else if (op >= 35 && op < 40) d.actions[op - 35] = string(b);
                else if (op == 40 || op == 41) pairs(b, op == 40 ? d.recolors : d.retextures);
                else if (op == 2 || op == 3 || op == 9 || (op >= 30 && op < 40)) string(b);
                else if (op == 43) {
                    u8(b);
                    while (u8(b) != 0) string(b);
                } else if (op == 12 || op == 44 || (op >= 49 && op <= 54)) b.getInt();
                else if (op == 25) {
                    u16(b);
                    u8(b);
                } else if (op == 48) {
                    b.getInt();
                    u8(b);
                } else if (op == 1
                        || (op >= 4 && op <= 8)
                        || op == 26
                        || op == 75
                        || op == 79
                        || (op >= 90 && op <= 99)
                        || (op >= 110 && op <= 112)
                        || op == 139
                        || op == 140
                        || op == 148
                        || op == 149) u16(b);
                else if (op == 27 || op == 42 || op == 113 || op == 114 || op == 115) u8(b);
                else if (op >= 100 && op < 110) b.getInt();
                else if (op == 161) {
                    int count = u16(b);
                    for (int i = 0; i < count; i++) u16(b);
                } else if (op == 249) {
                    int count = u8(b);
                    for (int i = 0; i < count; i++) {
                        int type = u8(b);
                        u8(b);
                        u8(b);
                        u8(b);
                        if (type == 1) string(b);
                        else b.getInt();
                    }
                } else if (op != 11 && op != 15 && op != 16 && op != 65 && op != 160 && op != 251)
                    throw new IllegalArgumentException("Unknown item opcode " + op);
            }
            throw new IllegalArgumentException("Unterminated definition");
        } catch (java.nio.BufferUnderflowException ex) {
            throw new IllegalArgumentException("Truncated cache definition", ex);
        }
    }

    private static int u8(ByteBuffer b) {
        return b.get() & 255;
    }

    private static int u16(ByteBuffer b) {
        return b.getShort() & 65535;
    }

    private static String string(ByteBuffer b) {
        int start = b.position();
        while (b.get() != 0) {}
        return new String(
                b.array(),
                start,
                b.position() - start - 1,
                java.nio.charset.Charset.forName("windows-1252"));
    }

    private static void pairs(ByteBuffer b, List<short[]> pairs) {
        int count = u8(b);
        for (int i = 0; i < count; i++) pairs.add(new short[] {b.getShort(), b.getShort()});
    }
}

package com.celebritymode.appearance;

import java.util.*;

import javax.inject.*;

/** Discovers current wearable cache items incrementally; no preset wardrobe or external data. */
@Singleton
public final class EquipmentCatalog {
    public static final class Item {
        public final int id, slot;
        public final String name, family;
        public final boolean members, twoHanded;

        Item(int id, FanModelFactory.Definition d) {
            this.id = id;
            slot = d.slot;
            name = d.name;
            members = d.members;
            twoHanded = d.wear2 == 5 || d.wear3 == 5;
            family = family(name);
        }
    }

    private final FanModelFactory models;
    private final Map<Integer, List<Item>> bySlot = new HashMap<>();
    private int[] ids;
    private int cursor, stride;

    @Inject
    public EquipmentCatalog(FanModelFactory models) {
        this.models = models;
    }

    public void advance(int budget) {
        if (ids == null) {
            ids = models.itemIds();
            stride = 7919;
            if (ids == null) return;
            while (ids.length > 0 && gcd(stride, ids.length) != 1) stride++;
        }
        for (int count = 0; cursor < ids.length && count < budget; count++, cursor++) {
            int id = ids[(int) ((long) cursor * stride % ids.length)];
            try {
                FanModelFactory.Definition d = models.readEquipment(id);
                if (d == null) {
                    ids = null;
                    return;
                } // Cache readiness retry without keeping an incomplete index.
                if (d.slot < 0
                        || d.models[0] < 0
                        || d.name.isEmpty()
                        || d.noteTemplate >= 0
                        || d.placeholderTemplate >= 0
                        || Arrays.stream(d.actions)
                                .noneMatch(
                                        action ->
                                                "Wear".equalsIgnoreCase(action)
                                                        || "Wield".equalsIgnoreCase(action)
                                                        || "Equip".equalsIgnoreCase(action)))
                    continue;
                String name = d.name.toLowerCase(Locale.ENGLISH);
                if (name.contains("broken")
                        || name.contains("inactive")
                        || name.contains("(l)")
                        || name.contains("(or)")
                        || name.contains("(uncharged)")
                        || name.startsWith("null")) continue;
                List<Item> pool = bySlot.computeIfAbsent(d.slot, k -> new ArrayList<>());
                pool.add(new Item(id, d));
            } catch (IllegalArgumentException ex) {
                /* Unknown future definition formats are excluded. */
            }
        }
    }

    public Item choose(int slot, FanGearTier tier, String affinity, Random random) {
        List<Item> pool = bySlot.getOrDefault(slot, Collections.emptyList());
        Item picked = null;
        int candidates = 0;
        boolean familyAvailable = false;
        if (affinity != null)
            for (Item item : pool)
                if (matches(item, tier) && item.family.equals(affinity)) {
                    familyAvailable = true;
                    break;
                }
        for (Item item : pool)
            if (matches(item, tier) && (!familyAvailable || item.family.equals(affinity)))
                if (random.nextInt(++candidates) == 0) picked = item;
        return picked;
    }

    static boolean matches(Item item, FanGearTier tier) {
        String name = item.name.toLowerCase(Locale.ENGLISH);
        switch (tier) {
            case DEFAULT_BOB:
                return false;
            case BRONZE_NOOB:
                return name.startsWith("bronze ")
                        || (item.slot == 1 && name.contains("cape"))
                        || (item.slot == 9 || item.slot == 10) && name.startsWith("leather ");
            case F2P_WARRIOR:
                return !item.members;
            case MODERN_GEAR:
                return item.id >= 20000;
            case MIDGAME_WARRIOR:
                return item.members;
            default:
                return true;
        }
    }

    static String family(String name) {
        String clean = name.toLowerCase(Locale.ENGLISH).replaceAll("[^a-z0-9 ]", "").trim();
        String[] words = clean.split(" +");
        return words.length > 1 && words[1].equals("moon") ? words[0] + " moon" : words[0];
    }

    public int size() {
        int size = 0;
        for (List<Item> items : bySlot.values()) size += items.size();
        return size;
    }

    public boolean complete() {
        return ids != null && cursor >= ids.length;
    }

    public void clear() {
        ids = null;
        cursor = 0;
        bySlot.clear();
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int next = a % b;
            a = b;
            b = next;
        }
        return a;
    }
}

